<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/audit.php';require_once __DIR__.'/../../includes/accounting_posting.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit;}verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');
try{
 if($action==='validate'){
  requireModulePermission('customer_orders','edit');$conn->beginTransaction();$q=$conn->prepare("SELECT * FROM customer_sales_orders WHERE id=? FOR UPDATE");$q->execute([$id]);$o=$q->fetch();if(!$o||$o['status']!=='Draft')throw new RuntimeException('Only Draft orders can be validated.');
  $q=$conn->prepare("SELECT i.product_id,i.quantity,p.product_name,p.stock_quantity,p.unit FROM customer_sales_order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=?");$q->execute([$id]);$rows=$q->fetchAll();$reserved=[];foreach($rows as $r)$reserved[(int)$r['product_id']]=($reserved[(int)$r['product_id']]??0)+(int)$r['quantity'];foreach($rows as $r)if((float)$r['stock_quantity']<$reserved[(int)$r['product_id']])throw new RuntimeException('Insufficient stock for '.$r['product_name'].'. Available '.$r['stock_quantity'].' '.$r['unit'].'.');
  $q=$conn->prepare("UPDATE customer_sales_orders SET status='Validated',validated_by=?,validated_at=NOW() WHERE id=?");$q->execute([(int)$_SESSION['user_id'],$id]);$conn->commit();$_SESSION['customer_order_flash']='Order validated and moved to Pending Invoices.';
 }elseif($action==='confirm'){
  requireModulePermission('customer_orders','edit');$conn->beginTransaction();$q=$conn->prepare("SELECT * FROM customer_sales_orders WHERE id=? FOR UPDATE");$q->execute([$id]);$o=$q->fetch();if(!$o||$o['status']!=='Validated')throw new RuntimeException('Only validated orders can be confirmed.');
  $q=$conn->prepare("SELECT i.*,p.product_name,p.stock_quantity,p.buying_price,p.unit FROM customer_sales_order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=? FOR UPDATE");$q->execute([$id]);$items=$q->fetchAll();$reserved=[];foreach($items as $it)$reserved[(int)$it['product_id']]=($reserved[(int)$it['product_id']]??0)+(int)$it['quantity'];foreach($items as $it)if((float)$it['stock_quantity']<$reserved[(int)$it['product_id']])throw new RuntimeException('Stock has changed. '.$it['product_name'].' is no longer available in the required quantity.');
  $credit=$conn->prepare("SELECT credit_limit,balance,customer_name FROM customers WHERE id=? FOR UPDATE");$credit->execute([$o['customer_id']]);$customerCredit=$credit->fetch();if(!$customerCredit)throw new RuntimeException('Customer record is no longer available.');$available=max(0,(float)$customerCredit['credit_limit']-(float)$customerCredit['balance']);$total=(float)$o['total_amount'];if((float)$customerCredit['credit_limit']>0&&$total>$available+0.001)throw new RuntimeException('Customer credit limit would be exceeded. Available credit: KES '.number_format($available,2).'.');$invoice='TMP-'.strtoupper(bin2hex(random_bytes(8)));$q=$conn->prepare("INSERT INTO sales(invoice_number,customer_id,price_list_id,user_id,sale_date,subtotal,discount,tax,total_amount,paid_amount,amount_tendered,balance,payment_method,sale_status,notes) VALUES(?,?,?,?,?,?,?,?,?,0,0,?,'Credit','Completed',?)");$q->execute([$invoice,$o['customer_id'],$o['price_list_id'],(int)$_SESSION['user_id'],date('Y-m-d H:i:s'),$o['subtotal'],$o['discount'],$o['tax'],$total,$total,'Customer order '.$o['order_number']]);$saleId=(int)$conn->lastInsertId();$invoice='INV-'.date('ymd').'-'.str_pad((string)$saleId,5,'0',STR_PAD_LEFT);$conn->prepare("UPDATE sales SET invoice_number=? WHERE id=?")->execute([$invoice,$saleId]);
  $ins=$conn->prepare("INSERT INTO sale_items(sale_id,product_id,quantity,price,discount,subtotal,buying_price,entered_quantity,sale_unit,conversion_factor,entered_unit_price) VALUES(?,?,?,?,0,?,?,?,?,?,?)");$up=$conn->prepare("UPDATE products SET stock_quantity=stock_quantity-? WHERE id=?");$mov=$conn->prepare("INSERT INTO stock_movements(product_id,user_id,movement_type,quantity,stock_before,stock_after,reference_type,reference_id,notes,movement_date) VALUES(?,?,?,?,?,?,?,?,?,?)");$uid=(int)$_SESSION['user_id'];$running=[];
  foreach($items as $it){$pid=(int)$it['product_id'];$before=$running[$pid]??(float)$it['stock_quantity'];$after=$before-(int)$it['quantity'];$running[$pid]=$after;$ins->execute([$saleId,$pid,$it['quantity'],$it['unit_price'],$it['subtotal'],$it['buying_price'],$it['entered_quantity'],$it['sale_unit'],$it['conversion_factor'],$it['entered_unit_price']]);$up->execute([$it['quantity'],$pid]);$mov->execute([$pid,$uid,'Sale',$it['quantity'],$before,$after,'sale',$saleId,'Customer order '.$o['order_number'],date('Y-m-d H:i:s')]);}
  $conn->prepare("UPDATE customers SET balance=balance+? WHERE id=?")->execute([$total,$o['customer_id']]);$conn->prepare("UPDATE customer_sales_orders SET status='Invoiced',sale_id=?,confirmed_by=?,confirmed_at=NOW() WHERE id=?")->execute([$saleId,$uid,$id]);
  recordAuditEvent($conn,'Confirm','customer_orders','Confirmed '.$o['order_number'].' as invoice '.$invoice,'customer_sales_order',$id,null,['sale_id'=>$saleId,'invoice_number'=>$invoice,'total_amount'=>$total]);
  if(dibonkeAccountingAutoPostingEnabled($conn)){$cost=0;foreach($items as $it)$cost+=(float)$it['buying_price']*(int)$it['quantity'];$rev=round($total-(float)$o['tax'],2);$lines=[dibonkeAccountingLine(dibonkeAccountingAccount($conn,'accounts_receivable','Asset'),'Customer invoice '.$invoice,$total,0),dibonkeAccountingLine(dibonkeAccountingAccount($conn,'sales_revenue','Income'),'Sales revenue',0,$rev)];if((float)$o['tax']>0)$lines[]=dibonkeAccountingLine(dibonkeAccountingAccount($conn,'vat_payable','Liability'),'Output VAT',0,(float)$o['tax']);if($cost>0){$lines[]=dibonkeAccountingLine(dibonkeAccountingAccount($conn,'cost_of_goods_sold','Expense'),'Cost of goods sold',$cost,0);$lines[]=dibonkeAccountingLine(dibonkeAccountingAccount($conn,'inventory','Asset'),'Inventory relieved',0,$cost);}dibonkeAccountingPostJournal($conn,'sale',$saleId,date('Y-m-d'),'Customer order '.$o['order_number'],$lines,$uid);}
  $conn->commit();$_SESSION['customer_order_flash']='Invoice '.$invoice.' confirmed. You can print it now.';header('Location: invoice.php?id='.$id);exit;
 }else throw new RuntimeException('Unknown action.');
 $_SESSION['customer_order_flash']=$_SESSION['customer_order_flash']??'Order updated.';header('Location: '.($action==='validate'?'pending.php':'index.php'));exit;
}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$_SESSION['customer_order_flash']='Action failed: '.$e->getMessage();header('Location: '.($action==='confirm'?'pending.php':'index.php'));exit;}
